#!/usr/bin/env python3
"""Write a BENCHMARKS.md-style sheet for hosts outside admin/bench-report's HOSTS.

Imports `report()` from a rind checkout and writes only under --out, which
must be outside that checkout. Does not read or write the checkout's
BENCHMARKS.md, benchmarks/, or benchmarks/gaps.toml.
"""

import argparse
import importlib.machinery
import importlib.util
import json
import sys
from pathlib import Path

GENERATED = (
    "<!-- Generated by `admin/bench-report render` from benchmarks/data, "
    "benchmarks/verified.toml, and benchmarks/gaps.toml. -->"
)
GENERATED_SIDE = (
    "<!-- Generated by calling report() in rind's admin/bench-report on host "
    "JSON from outside that script's HOSTS. This is not the repo's BENCHMARKS.md. -->"
)
PINNED = (
    "Each host builds with the pinned toolchain in the Nix dev shell, and runs "
    "`admin/bench-report` only when idle. Times are criterion's estimates."
)
PINNED_SIDE = (
    "Times are criterion's estimates from `admin/bench-report run`. A host measured "
    "through host-run.py kept that script's operations, criterion arguments, parsing, "
    "and JSON, and recorded a busy host or a rustc other than the Nix pin instead of "
    "refusing them. The toolchain and the load are whatever each host's JSON records. "
    "A host run outside the Nix dev shell, or while other work was on the machine, says "
    "so in its note. A host the JSON marks noisy had other work during the run."
)

NEEDED = ("report", "load_verified", "gaps_of", "label", "COLUMNS", "HOSTS", "REPORT", "REPORT_DIR")


def load_renderer(rind):
    path = rind / "admin" / "bench-report"
    if not path.is_file():
        sys.exit(f"render-side: no {path}")
    loader = importlib.machinery.SourceFileLoader("bench_report", str(path))
    spec = importlib.util.spec_from_loader("bench_report", loader)
    module = importlib.util.module_from_spec(spec)
    loader.exec_module(module)
    missing = [name for name in NEEDED if not hasattr(module, name)]
    if missing:
        sys.exit(
            "render-side: admin/bench-report is missing "
            + ", ".join(missing)
            + "; this script is out of date"
        )
    return module


def load_host(path):
    try:
        host = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as error:
        sys.exit(f"render-side: {path}: {error}")
    if host.get("status") != "ok":
        sys.exit(
            f"render-side: {path}: status {host.get('status')}: {host.get('reason', 'not ok')}"
        )
    name = host.get("host")
    if not isinstance(name, str) or not name or any(c.isspace() or c == "`" for c in name):
        sys.exit(f"render-side: {path}: host name must be a token without spaces or backticks")
    for key in ("results", "started", "commit", "os"):
        if key not in host:
            sys.exit(f"render-side: {path}: missing {key}")
    cpu = host.get("cpu") or {}
    if "model" not in cpu or "arch" not in cpu:
        sys.exit(f"render-side: {path}: missing cpu.model or cpu.arch")
    if not (host.get("toolchain") or {}).get("rustc"):
        sys.exit(f"render-side: {path}: missing toolchain.rustc")
    return name, host


def read_note(path):
    try:
        text = path.read_text(encoding="utf-8").strip()
    except OSError as error:
        sys.exit(f"render-side: {path}: {error}")
    if not text:
        sys.exit(f"render-side: {path}: empty note")
    if text.startswith("#") or "\n#" in text:
        sys.exit(f"render-side: {path}: a note is prose, not a Markdown heading")
    return text


def rewrite(markdown, module, hosts):
    for old, new, what in (
        (GENERATED, GENERATED_SIDE, "generated-by comment"),
        (PINNED, PINNED_SIDE, "toolchain sentence"),
    ):
        if old not in markdown:
            sys.exit(f"render-side: report() no longer contains the {what} this script replaces")
        markdown = markdown.replace(old, new, 1)
    marker = "## CPU tiers"
    verified = "## Verified code"
    if marker not in markdown or verified not in markdown:
        sys.exit("render-side: report() no longer has the sections this script replaces")
    head, _, rest = markdown.partition(marker)
    _, _, tail = rest.partition(verified)
    gaps = module.gaps_of(hosts, None)
    lines = [
        "## Gaps on these hosts",
        "",
        "Each operation where another library is more than 10% faster than rind, "
        "computed by `gaps_of` the way `admin/bench-report` computes gaps (`SLOWER` is 1.1). "
        "These are measurements. `benchmarks/gaps.toml` holds the maintainers' decisions for "
        "the hosts in `HOSTS`, and this sheet does not read or write it.",
        "",
    ]
    if gaps:
        lines += [
            "| Operation | On | rind's time over the fastest |",
            "|---|---|---|",
        ]
        order = list(hosts)
        ranked = sorted(gaps.items(), key=lambda item: (order.index(item[0][1]), -item[1][0]))
        for (row, host), (ratio, best) in ranked:
            shown = module.COLUMNS.get(best, best)
            lines.append(f"| {module.label(row)} | `{host}` | {ratio:.2f}× ({shown}) |")
    else:
        lines.append("None.")
    return head + "\n".join(lines) + "\n\n## Verified code" + tail


def outside(rind, path):
    return path != rind and rind not in path.parents


def main():
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--rind", required=True, type=Path, help="checkout to import, not to modify")
    parser.add_argument("--out", required=True, type=Path, help="directory outside that checkout")
    parser.add_argument(
        "--note",
        nargs=2,
        action="append",
        metavar=("HOST", "FILE"),
        default=[],
        help="one-paragraph note for HOST; else <json-stem>.note beside the JSON",
    )
    parser.add_argument("json", nargs="+", type=Path, help="status-ok host JSON, sheet order")
    args = parser.parse_args()

    rind = args.rind.resolve()
    out = args.out.resolve()
    if not outside(rind, out):
        sys.exit("render-side: --out is inside the rind checkout; pick a directory outside it")

    notes = {name: read_note(Path(path)) for name, path in args.note}
    hosts = {}
    table = {}
    for path in args.json:
        name, host = load_host(path)
        if name in hosts:
            sys.exit(f"render-side: two files are named {name}")
        beside = path.with_suffix(".note")
        if name not in notes and beside.is_file():
            notes[name] = read_note(beside)
        entry = {}
        if name in notes:
            entry["note"] = notes[name]
        table[name] = entry
        hosts[name] = host
    unused = sorted(set(notes) - set(hosts))
    if unused:
        sys.exit("render-side: notes for hosts with no JSON: " + ", ".join(unused))

    module = load_renderer(rind)
    module.HOSTS = table
    module.REPORT = str(out / "BENCHMARKS.md")
    module.REPORT_DIR = str(out / "benchmarks")
    verified = module.load_verified()
    files = module.report(hosts, None, verified, None)
    sheet = module.REPORT
    if sheet not in files:
        sys.exit("render-side: report() did not return the sheet")
    files[sheet] = rewrite(files[sheet], module, hosts)

    for path, content in files.items():
        dest = Path(path)
        if not outside(rind, dest):
            sys.exit(f"render-side: refused to write inside the rind checkout: {dest}")
        dest.parent.mkdir(parents=True, exist_ok=True)
        text = content if content.endswith("\n") else content + "\n"
        dest.write_text(text, encoding="utf-8")
    print(out / "BENCHMARKS.md")


if __name__ == "__main__":
    main()
